# ------------------------------------------------------------------ статус
def build_status(ctx: Ctx) -> str:
    d = load_ctx_data(ctx)
    recs = scan_records(ctx)
    per = {}
    for r in recs:
        base_coll = r.get("collection")
        buckets: dict[str, list] = {}
        for sec in ("rules", "catalog"):
            for it in r.get(sec, []) or []:
                c = it.get("collection") or base_coll
                if c:
                    buckets.setdefault(c, []).append((sec, it))
        if base_coll and base_coll not in buckets:
            buckets[base_coll] = []
        for c, items in buckets.items():
            p = per.setdefault(c, {"filled": 0, "todo": 0, "files": 0, "auto": 0})
            p["files"] += 1
            for sec, it in items:
                bad = is_todo(it.get("behavior")) if sec == "rules" else (is_todo(it.get("own_name")) or is_todo(it.get("behavior", "")))
                if bad:
                    p["todo"] += 1
                elif (r.get("meta") or {}).get("auto"):
                    p["auto"] += 1
                else:
                    p["filled"] += 1
            if r.get("collection") == c:
                p["todo"] += len(r.get("candidates", []) or [])
    lines = [f"# Статус: {ctx.game}", "", f"Обновлено: {time.strftime('%Y-%m-%d %H:%M')}. Реестр: `{ctx.registry_path.name}`.", "",
             "## Шаги", "", "| Шаг | Состояние | Заметка | с |", "|---|---|---|---|"]
    for s in STEPS[:-1]:
        v = ctx.st["steps"].get(s)
        lines.append(f"| {s} | {v['state'] if v else '-'} | {(v or {}).get('note', '')[:110]} | {(v or {}).get('seconds', '')} |")
    lines += ["", "## Коллекции", "", "| Семья | Коллекция | Авто | P | Обработчик | Записей | TODO | Состояние |", "|---|---|---|---|---|---|---|---|"]
    tally = {}
    rows = []
    for fam in d["families"]:
        for cid in fam["collections"]:
            c = d["coll"][cid]
            h = X.pick_handler(cid, d["registry"].get(cid, {}), c["automation"])
            p = per.get(cid)
            run = ctx.st["collections"].get(cid, {})
            if p and (p["filled"] or p["auto"]) and not p["todo"]:
                state = "done" if p["filled"] else "extracted"
            elif p and (p["filled"] or p["auto"]):
                state = "in_progress"
            elif p and p["todo"]:
                state = "skeleton"
            elif run.get("state"):
                state = run["state"]
            else:
                state = "pending"
            if h == "todo" and state in ("pending", "skeleton"):
                state = "todo"
            n = (p["filled"] + p["auto"]) if p else run.get("entries", 0)
            tally[state] = tally.get(state, 0) + 1
            rows.append({"collection": cid, "family": fam["id"], "automation": c["automation"], "priority": c["priority"],
                         "handler": h, "entries": n, "todo": p["todo"] if p else 0, "state": state, "note": run.get("note", "")})
            lines.append(f"| {fam['id']} | {cid} | {c['automation']} | {c['priority']} | {h} | {n} | {p['todo'] if p else 0} | {state} |")
    lines += ["", "Итого: " + ", ".join(f"{k} {v}" for k, v in sorted(tally.items())) + f" (из {len(rows)}).", ""]
    # системные скелеты
    sysrec = [r for r in recs if r["_rel"].startswith("systems/")]
    if sysrec:
        lines += ["## Системные записи (по корзинам)", "", "| Система | Корзина | Часть | Заполнено | TODO | Статус |", "|---|---|---|---|---|---|"]
        for r in sysrec:
            f, t = filled_stats(r)
            lines.append(f"| {r['system']['id']} {r['system']['slug']} | {(r['system'].get('buckets') or [''])[0]} | "
                         f"{(r.get('meta') or {}).get('part', '1/1')} | {f} | {t} | {r.get('status')} |")
    (ctx.work / "status.md").write_text("\n".join(lines) + "\n", encoding="utf-8")
    ctx.st["table"] = rows
    ctx.save()
    return "\n".join(lines[-3:-1] if False else [l for l in lines if l.startswith("Итого")])


def step_status(ctx: Ctx):
    s = build_status(ctx)
    log(f"[status] {s} -> {ctx.work / 'status.md'}")


